const raw = $input.first().json || {};
const b = raw.body ?? raw;

const event = String(b.event || '').toLowerCase();
const success = b.success;
const msg = String(b.message || '').toLowerCase();

const ERROR_EVENT_RE = /(fail|error|unreachable|critical|down|exception|timeout)/i;
const WARN_EVENT_RE = /(warn|disk|threshold|high.?usage|low.?space)/i;

const hasExplicitError = Boolean(
  b.error_message || b.error_output || b.s3_error || b.exception
);
const failed = success === false || success === 'false' || success === 0;
const diskWarn = b.disk_usage != null && b.threshold != null
  && Number(b.disk_usage) >= Number(b.threshold);
const eventBad = ERROR_EVENT_RE.test(event) || WARN_EVENT_RE.test(event)
  || ERROR_EVENT_RE.test(msg);
const isTest = event === 'test';

// Only errors / warnings — skip success, info, test pings
const isAlert = !isTest && (failed || hasExplicitError || diskWarn || eventBad);
if (!isAlert) {
  return [];
}

const severity = (failed || hasExplicitError || ERROR_EVENT_RE.test(event))
  ? 'error'
  : 'warning';
const emoji = severity === 'error' ? ':x:' : ':warning:';

const parts = [
  `${emoji} *Coolify ${severity}* · \`${b.event || 'unknown'}\``,
  b.message || '',
];
const details = [];
if (b.application_name) details.push(`*App:* ${b.application_name}`);
if (b.project) details.push(`*Project:* ${b.project}`);
if (b.environment) details.push(`*Env:* ${b.environment}`);
if (b.server_name) details.push(`*Server:* ${b.server_name}`);
if (b.database_name) details.push(`*DB:* ${b.database_name}`);
if (b.task_name) details.push(`*Task:* ${b.task_name}`);
if (b.container_name) details.push(`*Container:* ${b.container_name}`);
if (b.fqdn || b.preview_fqdn) details.push(`*FQDN:* ${b.fqdn || b.preview_fqdn}`);
if (b.disk_usage != null) {
  details.push(`*Disk:* ${b.disk_usage}% (threshold ${b.threshold}%)`);
}
if (b.error_message) details.push(`*Error:* ${b.error_message}`);
if (b.error_output) details.push(`*Error:* ${String(b.error_output).slice(0, 800)}`);
if (b.s3_error) details.push(`*S3:* ${b.s3_error}`);
if (b.output && failed) details.push(`*Output:* ${String(b.output).slice(0, 500)}`);
if (details.length) parts.push(details.join(' · '));
const link = b.deployment_url || b.url;
if (link) parts.push(`<${link}|Open in Coolify>`);

return [{
  json: {
    slackText: parts.filter(Boolean).join('\n'),
    severity,
    event: b.event || '',
  },
}];
